<script lang="ts">
 import {onMount} from 'svelte';
 import MapCanvas from './MapCanvas.svelte';import Chart from './Chart.svelte';import Dashboard from './Dashboard.svelte';import TelemetrySummary from './TelemetrySummary.svelte';import ComparisonEvidence from './ComparisonEvidence.svelte';import Icon from './Icon.svelte';import {datasetFormats,defaultSessionConfig, FIRST_CPU_SAMPLE_NOTE, formatRenderAge, inputTargetFps,isRenderStale,layerUnavailable,mapActivity,MEMORY_DOMAIN_NOTE,perceptionStages,profileConfig,recordEvent,GLOSSARY,inspectorRows,datasetCapabilities,sessionPhase,semanticName,traversabilityLabel,classNames,type DashboardEvent} from './dashboard';
 import {semanticRGB,cssRGB} from './colors';
 import veyraLogo from '../assets/veyra-logo.png';
 import {policies,type Json,type WireFrame} from '../core';import {nativeRuntimeUnavailableMessage} from '../api';
 import {acceptFrame,canPlayback,diagnosticMessage,processRss,telemetryFreshness,mergeSessionStatus,validationOutcome} from './session';
 let workspace=$state('Dashboard'),status=$state<Json>({state:'unconfigured',index:0,frames:0,policy:'distance_lod',speed:1}),telemetry=$state<Json>({}),desktop=$state<Json>({}),render=$state<Json>({}),info=$state<Json>({});
 let frame=$state.raw<WireFrame|null>(null),samples=$state<Json[]>([]),error=$state(''),notice=$state(''),busy=$state(false),catalog=$state<Json|null>(null),inspector=$state<Json|null>(null);
 let dataset=$state('generic'),sequence=$state(''),config=$state<Json>(defaultSessionConfig());
 let configText=$state(''),mode=$state('semantic'),showPoints=$state(true),showCells=$state(true),boundaries=$state(false),view=$state('orbit'),follow=$state(false),seekIndex=$state(0),preset=$state('LowResource'),viewMode=$state('both'),showRings=$state(false);
 function setViewMode(next:string){viewMode=next;showPoints=next!=='map';showCells=next!=='raw';}
 let report=$state<Json|null>(null),previousReport=$state<Json|null>(null),benchmarkState=$state('idle'),benchmarkCount=$state(100),validationState=$state('idle'),validationResult=$state<Json|null>(null);
 let events=$state<DashboardEvent[]>([]);
 let now=$state(Date.now()),awaitingFrame=$state(false);
 const playbackEnabled=()=>canPlayback(status,busy);
 const labels:Record<string,string>={uniform5:'Uniform 5 cm',uniform40:'Uniform 40 cm',distance_lod:'Distance LOD',utility_lod:'Utility LOD'};
 const format=(value:any,decimals=1)=>typeof value==='number'&&Number.isFinite(value)?value.toLocaleString(undefined,{maximumFractionDigits:decimals}):'—';
 const mb=(value:any)=>typeof value==='number'?format(value/1048576)+' MB':'—';
 function rows(value:Json|null){const mapping=value?.mapping??value;return Object.entries(mapping?.policies??{}) as [string,Json][];}
 function quality(value:Json){return value.aggregate?.quality?.at(-1)?.elevation_vs_fine_reference?.rmse_m;}
 async function action(fn:()=>Promise<any>){if(busy)return;busy=true;error='';notice='';try{return await fn();}catch(e){error=e instanceof Error?e.message:String(e);awaitingFrame=false;}finally{busy=false;}}
 function clearSessionView(){frame=null;telemetry={};render={};samples=[];inspector=null;}
 async function command(name:string,args:Json={}){return action(async()=>{const reload=['sequence','reset','policy'].includes(name);if(reload){clearSessionView();awaitingFrame=true;}const r=await window.veyra.command(name,args);if(r.status)status=mergeSessionStatus(status,r.status);if(reload){const preview=await window.veyra.command('step');if(preview.status)status=preview.status;}return r;});}
let governorOverride=$state('automatic');
function syncGovernorOverride(value:unknown){if(value==='automatic'||value==='disabled'||value==='conserve')governorOverride=value;}
 async function setGovernor(mode:string){const previous=governorOverride;governorOverride=mode;const response=await command('governor',{mode});if(!response)governorOverride=previous;}
 async function setLayer(layer:string){const response=await command('layer',{layer});if(response){mode=layer;notice=`Layer changed to ${layer}.`;}}
 async function stopRuntime(){await action(async()=>{const response=await window.veyra.stop();if(response?.status)status=response.status;clearSessionView();awaitingFrame=false;notice='Runtime stopped. Open the dataset again to begin a new session.';});}
 async function runValidation(){await action(async()=>{validationState='running';validationResult=null;try{const response=await window.veyra.command('validation');if(response?.status)status=response.status;if(response?.result)validationResult=response.result;validationState=response?.result?.status==='pass'?'pass':'fail';}catch(error){validationState='fail';throw error;}});}
 async function runBenchmark(){await action(async()=>{benchmarkState='running';try{const response=await window.veyra.command('benchmark',{dataset:status.dataset,sequence:status.sequence,count:benchmarkCount});if(response.result?.report){report=response.result.report;benchmarkState='complete';}}catch(e){benchmarkState='failed';throw e;}});}
 async function restartRuntime(){await action(async()=>{clearSessionView();awaitingFrame=true;const response=await window.veyra.restart();if(response.status)status=response.status;if(status.frames){const preview=await window.veyra.command('step');if(preview.status)status=preview.status;}else{awaitingFrame=false;notice='Runtime restarted. Open a dataset preview to continue.';}});}
function confirmSaved(ok:unknown,saved:string,cancelled:string){notice=ok?saved:cancelled;}
 function refreshText(){configText=JSON.stringify(config,null,2);}
 async function chooseDataset(){await action(async()=>{const response=await window.veyra.chooseDataset(dataset);if(!response)return;catalog=response.result??response;const first=catalog!.sequences?.find((s:Json)=>s.frames>0);sequence=first?.id??'';config={...config,dataset,dataset_root:catalog!.root,sequence};refreshText();notice=first?'Dataset inspected. Select a sequence, then open its preview.':'No supported frames found. Check the dataset format and selected directory.';});}
 async function configure(){await action(async()=>{const next=JSON.parse(configText||JSON.stringify(config));clearSessionView();awaitingFrame=true;notice='Starting runtime and processing the first frame…';workspace='Map';const response=await window.veyra.configure(next);config=next;syncGovernorOverride(next.map?.governor_override);if(response.status)status=response.status;const first=await window.veyra.command('step');if(first.status)status={...status,...first.status};notice=frame?'Preview received. Use Play to continue.':'Frame processed. Waiting for the visualization to arrive…';});}
 async function openDirect(){await configure();}
 function applyPreset(){config=profileConfig(config,preset);governorOverride='automatic';refreshText();}
 onMount(()=>{
  refreshText();if(!window.veyra){error=nativeRuntimeUnavailableMessage;return;}
  void action(async()=>{info=await window.veyra.info();if(info.status)status=info.status;});
  const off=window.veyra.onEvent(event=>{
   events=recordEvent(events,event);
   const diagnostic=diagnosticMessage(event);if(diagnostic){error=diagnostic;awaitingFrame=false;}
   if(event.type==='status'){status={...status,...event};if(event.error)error=event.error.process+': '+event.error.message;}
   if(event.type==='telemetry'){telemetry=event;const latency=event.latency_ms??{},rss=processRss(event.processes??[]);samples=[...samples,{timestamp:event.timestamp,fps:event.fps,p95:latency.end_to_end?.p95,rss:rss===null?null:rss/1048576,mapping:latency.mapping,perception:latency.perception}].slice(-300);}
   if(event.type==='desktop_telemetry')desktop=event;
   if(event.type==='benchmark'){benchmarkState=event.state;if(event.report)report=event.report;if(event.error)error=String(event.error.message??event.error);}
   if(event.type==='validation'){validationState=validationOutcome(event);if(event.result)validationResult=event.result;}
  });
  const offVisual=window.veyra.onVisualization(value=>{try{if(!acceptFrame(value,frame,status.state,awaitingFrame))return;frame=value;awaitingFrame=false;notice='';}catch(e){error=`Visualization failed: ${e instanceof Error?e.message:String(e)}`;awaitingFrame=false;}});
  const clock=setInterval(()=>{now=Date.now();},1000);
  const subscriptionError=(event:Event)=>{error=`Desktop event connection failed: ${(event as CustomEvent).detail}`;};
  window.addEventListener('veyra-subscription-error',subscriptionError);
  return()=>{off();offVisual();clearInterval(clock);window.removeEventListener('veyra-subscription-error',subscriptionError);};
 });
</script>

<div class="application">
 <aside class="rail">
  <div class="brand"><img class="brand-logo" src={veyraLogo} alt="Veyra logo"/><span>VEYRA<small>Map smarter.<br/>Move safer.</small></span></div>
  <nav aria-label="Workspaces">{#each [['Dashboard','Dashboard','home'],['Map','Live Mapping','map'],['Datasets','Datasets','database'],['Performance','Performance','chart'],['Benchmarks','Validation & benchmarks','chart']] as [key,name,icon]}<button class:active={workspace===key} onclick={()=>workspace=key}><Icon name={icon}/>{name}</button>{/each}</nav>
  <div class="rail-bottom"><div class="system-health"><h3><i class:online={['ready','running','paused','ended'].includes(status.state)}></i>{['ready','running','paused','ended'].includes(status.state)?'System Online':'Runtime Standby'}</h3><p>{status.dataset??'No dataset open'}{status.sequence?' · '+status.sequence:''}</p></div><strong>VEYRA · SIH 2026</strong><p>Adaptive Mapping for<br/>Safer Autonomy</p><span class="muted">v{info.version??'0.1.0'} · {info.platform??'desktop'}</span></div>
 </aside>
 <main>
  <header><div class="header-title"><div><h1>{workspace==='Dashboard'?'Adaptive 2.5D LiDAR Dashboard':workspace==='Map'?'Live Mapping':workspace==='Performance'?'Runtime Performance':workspace==='Benchmarks'?'Policy Benchmarks':workspace==='Datasets'?'Dataset Management':'Session Settings'}</h1><span class="status-pill" class:running={status.state==='running'} class:failed={status.state==='error'}><i></i>{status.state==='running'?'Live':status.state}</span>{#if telemetryFreshness(telemetry,now)==='Stale'}<span class="stale-badge" title="Flagged by the desktop shell: this telemetry arrived more than 30 s after its timestamp. Values may be outdated.">STALE</span>{/if}</div><p>Real-time mapping · Adaptive resolution · Semantic understanding</p></div><div class="header-right"><div class="scenario-control"><span>Session</span><div><Icon name="car" size={17}/><span id="header-scenario">{status.sequence?`${status.dataset??'Dataset'} · ${status.sequence} · ${status.frames??0} frames`:'No dataset selected'}</span></div></div><button class="export-button" onclick={()=>action(async()=>{const saved=await window.veyra.diagnostics();confirmSaved(saved,'Diagnostics exported.','Diagnostics export cancelled — no file written.');})}><Icon name="export" size={18}/>Export</button><div class="local-profile"><span>V</span><div><strong>Local Session</strong><small>Veyra Runtime</small></div></div></div></header>
  {#if error}<div class="alert" role="alert"><span>{error}</span><button disabled={busy} onclick={restartRuntime}>Restart runtime</button><button aria-label="Dismiss error" onclick={()=>error=''}>×</button></div>{/if}
  {#if notice}<div class="notice" role="status">{notice}</div>{/if}
  {#if workspace==='Dashboard'}
   <Dashboard {status} {telemetry} {frame} {report} {events} {busy} {awaitingFrame} openDataset={()=>workspace='Datasets'} openPerformance={()=>workspace='Performance'} openMap={()=>workspace='Map'} openBenchmarks={()=>workspace='Benchmarks'}/>
  {:else if workspace==='Map'}
   <div class="map-workspace">
    <aside class="layer-panel"><div class="panel-heading">VIEW <span>RAW / MAP</span></div>
     <div class="segmented" role="group" aria-label="Raw and map visibility">{#each [['raw','Raw'],['both','Both'],['map','Map']] as [value,label]}<button class:active={viewMode===value} onclick={()=>setViewMode(value)}>{label}</button>{/each}</div>
     <p class="hint">Raw LiDAR points vs adaptive 2.5D map cells — never the same thing.</p><div class="separator"></div>
     <div class="panel-heading">LAYERS <span>DISPLAY</span></div>
     {#each [['semantic','Semantic'],['elevation','Elevation'],['ground','Ground'],['terrain','Traversability'],['motion','Motion'],['lod','LOD resolution'],['utility','Utility']] as [value,label]}
      <button class="layer" class:selected={mode===value} onclick={()=>setLayer(value)} disabled={!playbackEnabled()} title={value==='lod'?'Cell size by level: L0 5 cm, L1 10 cm, L2 20 cm, L3 40 cm':value==='utility'?'Per-cell promotion signal 0–1 (quality-gated)':label}><span class="layer-dot" style:background={value==='lod'?'#45d3c9':undefined}></span>{label}{#if layerUnavailable(frame,value)}<small>n/a</small>{/if}</button>
     {/each}
     <div class="separator"></div><label class="toggle"><input type="checkbox" bind:checked={boundaries}/>Cell boundaries</label><label class="toggle"><input type="checkbox" bind:checked={follow}/>Follow robot</label><label class="toggle" title="DistanceLOD bands: 0–10 m → 5 cm, 10–30 m → 10 cm, 30–60 m → 20 cm, 60–100 m → 40 cm"><input type="checkbox" bind:checked={showRings}/>Range rings</label>
     <div class="panel-heading space-top" title={GLOSSARY['LOD']}>RESOLUTION <span title={GLOSSARY['LOD']}>ⓘ</span></div>{#each ['5 cm','10 cm','20 cm','40 cm'] as level,i}<div class="legend-row"><i style:background={['#33d9f2','#4dd980','#ffb340','#d966d9'][i]}></i><span>L{i} · {level}</span><b>{format(telemetry.map?.cells_by_level?.[i],0)}</b></div>{/each}
     <div class="legend-row"><span>Splits / s</span><b>{format(telemetry.map?.splits_per_second,2)}</b></div><div class="legend-row"><span>Merges / s</span><b>{format(telemetry.map?.merges_per_second,2)}</b></div>
     {#if inspector}<div class="inspector"><div class="panel-heading">CELL INSPECTOR <span>MEASURED</span></div>{#each inspectorRows(inspector) as row}<div title={row.hint}><span>{row.label}</span><b>{row.value}</b></div>{/each}<button onclick={()=>inspector=null}>Close</button></div>{:else}<p class="hint">Click a map cell to inspect its stored XY + height/statistics.</p>{/if}
    </aside>
    <section class="map-stage" aria-label="LiDAR and adaptive map">
     {#if showCells}<div class="representation-banner" title={GLOSSARY['2.5D']}><strong>Representation · Adaptive 2.5D Grid</strong><span>Rendered in 3D · Stored as XY cells + height/statistics</span><details><summary>What is 2.5D?</summary><p>Veyra stores one adaptive XY cell containing height and scene statistics rather than maintaining a dense XYZ voxel volume. (X,Y) → elevation + statistics.</p></details></div>{/if}
     <MapCanvas {frame} {mode} {showPoints} {showCells} {boundaries} {view} {follow} {showRings} onStats={value=>render={...render,...value,updated_at:Date.now()}} onInspect={value=>inspector=value}/>
     <div class="map-toolbar"><div class="segmented">{#each ['orbit','top','driver'] as camera}<button class:active={view===camera} onclick={()=>view=camera}>{camera}</button>{/each}</div><span class="policy-badge" title="Active mapping policy driving the mapper — not just a dropdown state">Policy · {labels[status.policy]??status.policy??'—'}</span>
     {#if frame&&(mode==='semantic')}<div class="map-legend" aria-label="Semantic legend"><span class="legend-title">Classes · {frame?.metadata.pipeline_status?.semantic==='ground_truth'?'dataset ground truth':'model inference'}</span>{#each classNames.map((name,id)=>({name,id})).filter(item=>item.id!==0) as item}<span><i style:background={cssRGB(semanticRGB(item.id))}></i>{item.name}</span>{/each}<span><i style:background={cssRGB(semanticRGB(0))}></i>Unknown</span></div>{/if}
     {#if frame&&mode==='terrain'}<div class="map-legend" aria-label="Traversability legend"><span><i style:background="#33d980"></i>Drivable</span><span><i style:background="#f24d59"></i>Non-drivable</span><span><i style:background="#59616b"></i>Unknown — never drivable</span></div>{/if}
     {#if frame&&mode==='motion'}<div class="map-legend" aria-label="Motion legend"><span><i style:background="#336699"></i>STATIC</span><span><i style:background="#b35533"></i>MOVING</span><span><i style:background="#59616b"></i>UNKNOWN</span></div>{/if}<button onclick={()=>action(async()=>{const saved=await window.veyra.screenshot();confirmSaved(saved,'Screenshot saved.','Screenshot cancelled — no file written.');})}>↓ Screenshot</button></div>
     {#if !frame}<div class="map-empty" role="status"><h2>{error?'Preview unavailable':awaitingFrame?'Processing your first frame…':'Open a dataset to begin'}</h2><p>{error?'The error above explains what failed. Return to Dataset to check the session.':awaitingFrame?'The runtime is preparing LiDAR points and map cells. The preview appears when those bytes reach this viewer.':'Choose a dataset directory and sequence, then open its preview.'}</p>{#if !awaitingFrame}<button class="primary" onclick={()=>workspace='Datasets'}>Choose dataset →</button>{/if}</div>{/if}
     <div class="map-coordinate"><span>WORLD · ODOM</span><span>Frame {frame?.metadata.frame_id??status.index??'—'} · {frame?.metadata.dataset??status.dataset??'—'}/{frame?.metadata.sequence??status.sequence??'—'} · {format(frame?.metadata.n_points,0)} pts · {frame?.metadata.range_m?`≤ ${frame.metadata.range_m} m`:'full range'}</span><span>{format(render.source_points??frame?.metadata.points?.count,0)} source points · {format(render.rendered_points??frame?.metadata.points?.count,0)} rendered · {format(render.source_cells??frame?.metadata.cells?.count,0)} source cells · {render.sampling_active?'SAMPLING ACTIVE':'FULL VIEW'}</span></div>
     {#if frame&&mode==='motion'&&layerUnavailable(frame,'motion')}<div class="layer-warning">Motion evidence unavailable for this dataset — no dataset timestamps, so nothing is tracked or drawn as moving. Static map evidence is unaffected.</div>
     {:else if frame&&layerUnavailable(frame,mode)}<div class="layer-warning">{mode[0].toUpperCase()+mode.slice(1)} values are unavailable in the current map snapshot.</div>{/if}
     <details class="event-drawer"><summary>Events / Diagnostics ({events.length})</summary><div class="event-list">{#each events.slice(-30).reverse() as event}<div class="event-item"><i class:error={event.kind==='error'}></i><time>{new Date(event.time).toLocaleTimeString(undefined,{hour12:false})}</time><p>{event.message}</p></div>{:else}<div class="events-empty">No runtime events yet.<span>Session changes and backend diagnostics appear here.</span></div>{/each}</div></details>
    </section>
   </div>
   <div class="playback"><div class="playback-buttons"><button title="Reset map" disabled={!playbackEnabled()} onclick={()=>command('reset')}>↺</button><button class="play-button" disabled={!playbackEnabled()} onclick={()=>command(status.state==='running'?'pause':'start')}>{status.state==='running'?'Ⅱ':'▶'}</button><button title="Step frame" disabled={!playbackEnabled()} onclick={()=>command('step')}>▸|</button></div><div class="timeline"><div><span>FRAME {format(status.index,0)}</span><span>{format(status.frames,0)} frames</span></div><input aria-label="Seek frame" type="range" min="0" max={Math.max(0,(status.frames??1)-1)} value={status.index??0} oninput={event=>seekIndex=Number(event.currentTarget.value)} onchange={()=>command('seek',{index:seekIndex})} disabled={!playbackEnabled()}/></div><select disabled={!playbackEnabled()} aria-label="Playback speed" value={status.speed??1} onchange={event=>command('speed',{speed:Number(event.currentTarget.value)})}>{#each [.25,.5,1,2,4,8] as speed}<option value={speed}>{speed}×</option>{/each}</select><select disabled={!playbackEnabled()} aria-label="Mapping policy" value={status.policy??'distance_lod'} onchange={event=>command('policy',{policy:event.currentTarget.value})}>{#each policies as policy}<option value={policy}>{labels[policy]}</option>{/each}</select></div>
   <div class="metric-strip"><div><span>PROCESSING FPS</span><b>{format(telemetry.fps)}</b></div><div title="Target playback rate = session playback.fps × speed (Python tick scheduler). Shows — when the session has no playback rate."><span>INPUT TARGET</span><b>{format(inputTargetFps(config,status))} <small>fps</small></b></div><div title={GLOSSARY['p95']}><span>E2E p95 ⓘ</span><b>{format(telemetry.latency_ms?.end_to_end?.p95)} <small>ms</small></b></div><div title="C++ map-update stage latency p95 (measured per frame)."><span>MAP p95</span><b>{format(telemetry.latency_ms?.mapping_p95??telemetry.latency_ms?.mapping,3)} <small>ms</small></b></div><div title={GLOSSARY['RSS']}><span>MAPPER RSS ⓘ</span><b>{mb(telemetry.processes?.find((p:Json)=>p.name==='mapper')?.rss_bytes)}</b></div><div title="Live C++ snapshot payload bytes (measured)."><span>MAP MEMORY</span><b>{mb(telemetry.map?.logical_bytes)}</b></div><div title={GLOSSARY['DistanceLOD']}><span>POLICY ⓘ</span><b>{labels[status.policy]??status.policy??'—'}</b></div><div><span>ACTIVE CELLS</span><b>{format(telemetry.map?.active_cells,0)}</b></div><div title="Three.js renderer throughput from the Map viewport (~1 s window). Persists after leaving Map; marked stale off-Map."><span>RENDER FPS{#if isRenderStale(render)} · STALE{/if}</span><b>{format(render.fps)}</b></div><div><span>DROPPED FRAMES</span><b>{format(telemetry.dropped_frames,0)}</b></div></div>
  {:else if workspace==='Performance'}
   <TelemetrySummary {telemetry} renderer={render} {now} />
   <div class="workspace-scroll"><div class="page-intro"><div><h2>Every stage, accounted for.</h2><p>Live process measurements. Rolling history retains the latest 300 samples.</p></div><span class="chip">{status.config_digest?.slice(0,12)??'NO SESSION'}</span></div>
    <div class="stats-grid">{#each [['Processing FPS',telemetry.fps,'fps'],['Frame p50',telemetry.latency_ms?.end_to_end?.p50,'ms'],['Frame p95',telemetry.latency_ms?.end_to_end?.p95,'ms'],['Frame p99',telemetry.latency_ms?.end_to_end?.p99,'ms']] as [label,value,unit]}<div class="stat-card"><span>{label}</span><strong>{format(value)} <small>{unit}</small></strong></div>{/each}</div>
    <div class="chart-grid"><section class="card"><h3>Throughput <span>FPS</span></h3><Chart {samples} metric="fps" label="Processing FPS"/></section><section class="card"><h3>End-to-end latency <span>p95 · ms</span></h3><Chart {samples} metric="p95" label="Frame p95" color="#c29cff"/></section><section class="card"><h3>Backend process memory <span>RSS · MB</span></h3><Chart {samples} metric="rss" label="Python + mapper RSS" color="#ffba6b"/></section><section class="card"><h3>Mapper latency <span>ms</span></h3><Chart {samples} metric="mapping" label="Mapping" color="#78b9ff"/></section></div>
    <div class="two-columns"><section class="card"><h3>Processes <span>CPU / memory</span></h3><table><thead><tr><th>Process</th><th>PID</th><th>CPU</th><th>RSS</th></tr></thead><tbody>{#each [...(telemetry.processes??[]),...(desktop.processes??[])] as process}<tr><td>{process.name}</td><td>{process.pid??'—'}</td><td>{format(process.cpu_percent)}%</td><td>{mb(process.rss_bytes)}</td></tr>{/each}</tbody></table><p class="hint">CPU may exceed 100% across cores. Unavailable measurements display —. {FIRST_CPU_SAMPLE_NOTE} Python rows are measured per frame by the Python reporter; desktop process rows are emitted only when the native shell can measure them. {MEMORY_DOMAIN_NOTE}</p></section><section class="card"><h3>Frame stages <span>ms</span></h3>{#each [['Perception',telemetry.latency_ms?.perception],['Bridge / IPC',telemetry.latency_ms?.ipc],['C++ mapping',telemetry.latency_ms?.mapping],['Visualization preparation',telemetry.latency_ms?.visualization],[`Renderer${(render?.fps!=null||render?.latency_ms!=null)?' · STALE':''}`,render.latency_ms],...Object.entries(telemetry.perception_stages_ms??{})] as [label,value]}<div class="data-row"><span>{label}</span><b>{format(value,2)}</b></div>{/each}<p class="hint">Renderer values come from the Map viewport (~1 s Three.js window). Last update: {render?.updated_at?new Date(render.updated_at).toLocaleTimeString(undefined,{hour12:false}):'—'}{render?.updated_at?` (${formatRenderAge(render)})`:''}; values persist after leaving Map and are marked stale off-Map.</p></section></div>
    <section class="card perception-status"><h3>Perception evidence <span>{frame?.metadata.dataset??'NO FRAME'}</span></h3><div class="stage-grid">{#each perceptionStages(frame) as stage}<div class="stage-item"><span>{stage.label}</span><strong class:stage-available={stage.status==='available'||stage.status==='model'||stage.status==='ground_truth'} class:stage-unavailable={stage.status==='unavailable'||stage.status==='invalid'}>{stage.status}</strong><small>{format(stage.latency,2)} ms</small></div>{/each}</div><p class="hint">Status is reported by the active pipeline; unavailable and skipped evidence is never rendered as measured data.</p></section>
    <div class="two-columns"><section class="card"><h3>Map allocation</h3>{#each mapActivity(telemetry) as [label,value]}<div class="data-row"><span>{label}</span><b>{label.includes('bytes')?mb(value):format(value,label.includes('second')?2:0)}</b></div>{/each}<p class="hint">{MEMORY_DOMAIN_NOTE} Map allocation shows live C++ snapshot bytes; compare only within this card.</p></section><section class="card"><h3>Resource governor <span>{telemetry.governor?.state??'unavailable'}</span></h3><label for="governor-override">Manual override</label><select id="governor-override" aria-label="Governor override" value={governorOverride} title={busy?'Governor control unavailable while a command is running.':!status.frames?'Configure a dataset session before overriding the governor.':'Manual governor override. Backend state is shown above.'} disabled={!playbackEnabled()} onchange={event=>{void setGovernor(event.currentTarget.value);}}><option value="automatic">Automatic</option><option value="disabled">Disabled (debug)</option><option value="conserve">Conserve resources</option></select><div class="data-row"><span>Queue depth</span><b>{format(telemetry.queue_depth,0)}</b></div><div class="data-row"><span>Dropped frames</span><b>{format(telemetry.dropped_frames,0)}</b></div><div class="data-row"><span>Visualization superseded</span><b>{format(telemetry.visualization_dropped,0)}</b></div><div class="data-row"><span>Desktop updates superseded</span><b>{format(desktop.ui_visualization_dropped,0)}</b></div>{#if desktop.ui_visualization_dropped==null}<p class="hint">Desktop shell counter unavailable — this shell emits no desktop_telemetry (Tauri).</p>{/if}<pre>{JSON.stringify(telemetry.governor?.budget??{budget:'unavailable'},null,2)}</pre></section></div>
   </div>
  {:else if workspace==='Benchmarks'}
   <div class="workspace-scroll">
   <ComparisonEvidence {report} />
   <section class="card runtime-actions"><h3>Session validation <span>{validationState.toUpperCase()}</span></h3><p class="hint">Runs the configured real dataset frame through perception and the mapper. It is a live smoke validation, not a replacement for repository CI.</p><button class="primary" disabled={busy||!status.dataset} onclick={runValidation}>Run session validation</button>{#if validationResult}<table><tbody>
      <tr><td>Result</td><td><strong>{String(validationResult.status??validationState).toUpperCase()}</strong> (real validator — never fabricated)</td></tr>
      <tr><td>Dataset / sequence</td><td>{validationResult.dataset??status.dataset??'—'} / {validationResult.sequence??status.sequence??'—'}</td></tr>
      <tr><td>Frame / points</td><td>{validationResult.frame??'—'} / {format(validationResult.points,0)}</td></tr>
      <tr><td>Semantic / ground / terrain</td><td>{validationResult.semantic??'—'} / {validationResult.ground??'—'} / {validationResult.terrain??'—'}</td></tr>
      <tr><td>Map</td><td>{validationResult.map??'—'}</td></tr>
      <tr><td>Policy</td><td>{labels[status.policy]??status.policy??'—'}</td></tr>
      <tr><td>Elapsed</td><td>{format(validationResult.elapsed_ms,1)} ms</td></tr>
      <tr><td>Commit / hardware</td><td>{info.commit??'N/A'} / {info.platform??'N/A'}</td></tr>
     </tbody></table><details><summary>Raw validator output</summary><pre>{JSON.stringify(validationResult,null,2)}</pre></details>{/if}</section>
   <div class="page-intro"><div><h2>Quality has a resource cost.</h2><p>Compare all four policies using the same report schema as CI.</p></div><span class="chip">{benchmarkState.toUpperCase()}</span></div><section class="card benchmark-controls"><div><label for="benchmark-count">Frames</label><input id="benchmark-count" type="number" min="1" max="100000" bind:value={benchmarkCount}/></div><button class="primary" disabled={busy||!status.dataset} onclick={runBenchmark}>Run four-policy benchmark</button><button onclick={()=>action(async()=>{const loaded=await window.veyra.openReport();if(loaded){previousReport=report;report=loaded;}})}>Open report</button><button disabled={!report} onclick={()=>action(async()=>{const saved=await window.veyra.exportReport(report!);confirmSaved(saved,'Benchmark report exported.','Benchmark export cancelled — no file written.');})}>Export JSON</button><button onclick={()=>action(async()=>{previousReport=await window.veyra.openReport();})}>Compare previous run</button></section>
    {#if report}{#if previousReport}<section class="card"><h3>Previous run comparison</h3><table><thead><tr><th>Policy</th><th>Current p95</th><th>Previous p95</th><th>Current RMSE</th><th>Previous RMSE</th></tr></thead><tbody>{#each rows(report) as [policy,result]}{@const previous=rows(previousReport).find(([key])=>key===policy)?.[1]}<tr><td>{labels[policy]??policy}</td><td>{format(result.aggregate?.stage_latency_ns?.map_update?.p95/1e6)} ms</td><td>{format(previous?.aggregate?.stage_latency_ns?.map_update?.p95/1e6)} ms</td><td>{format(quality(result),4)}</td><td>{previous?format(quality(previous),4):'—'}</td></tr>{/each}</tbody></table></section>{/if}<details class="card"><summary>Full benchmark artifact</summary><pre>{JSON.stringify(report,null,2)}</pre></details>{:else}<div class="blank-card"><span>▤</span><h2>No benchmark loaded</h2><p>Configure a dataset session, then run a measured comparison.<br/>Existing JSON artifacts can be opened at any time.</p></div>{/if}
   </div>
  {:else}
   <section class="card runtime-actions"><h3>Session control <span>{status.state?.toUpperCase()??'UNKNOWN'}</span></h3><p class="hint">Opening a preview starts the backend. Playback controls are in Live Mapping; Stop releases the session.</p><button disabled={busy||!status.dataset} onclick={stopRuntime}>Stop session</button><button disabled={busy||!status.dataset} onclick={restartRuntime}>Restart</button></section>
   <div class="workspace-scroll"><div class="page-intro"><div><h2>Choose a dataset, then view its first frame.</h2><p>1. Choose directory → 2. Select sequence → 3. Open preview → Play → Inspect metrics → Validate.</p></div><button onclick={()=>action(async()=>{const loaded=await window.veyra.openConfig();if(loaded){config=loaded;dataset=loaded.dataset??dataset;sequence=loaded.sequence??'';syncGovernorOverride(loaded.map?.governor_override);refreshText();notice='Configuration loaded. Choose its dataset directory before applying.';}})}>Import configuration</button></div>
    <div class="two-columns"><section class="card"><h3>Dataset <span>LOCAL FILES</span></h3><label for="dataset-format">Dataset format</label><select id="dataset-format" bind:value={dataset} disabled={busy} onchange={()=>{catalog=null;sequence='';config={...config,dataset,dataset_root:'',sequence:''};refreshText();}}>{#each datasetFormats as [value,label]}<option value={value}>{label}</option>{/each}</select><button class="wide" disabled={busy} onclick={chooseDataset}>Choose dataset directory…</button>{#if catalog}<div class="dataset-result"><span class="chip">{catalog.status}</span><p>{catalog.root}</p>{#each catalog.diagnostics??[] as diagnostic}<p class="hint">{diagnostic}</p>{/each}</div><label for="sequence">Sequence</label><select id="sequence" disabled={busy} bind:value={sequence} onchange={()=>{config={...config,sequence};refreshText();}}>{#each catalog.sequences??[] as seq}<option value={seq.id}>{seq.id} · {seq.frames} frames · {seq.labels} labels</option>{/each}</select><table><thead><tr><th>Sequence</th><th>Frames</th><th>Pose</th><th>Time</th></tr></thead><tbody>{#each catalog.sequences??[] as seq}<tr><td>{seq.id}</td><td>{seq.frames}</td><td>{seq.poses===null?'unknown':seq.poses?'yes':'no'}</td><td>{seq.timestamps===null?'unknown':seq.timestamps?'yes':'no'}</td></tr>{/each}</tbody></table>
     {@const caps=datasetCapabilities(catalog,sequence)}
     <div class="panel-heading space-top">SELECTED SEQUENCE <span class="chip phase-chip">{sessionPhase(catalog,status,awaitingFrame)}</span></div>
     <table class="capability-table"><tbody>
      <tr><td>Frames</td><td>{caps.frames??'—'}</td></tr>
      <tr><td>Labels</td><td>{caps.labels??'none — geometry only'}</td></tr>
      <tr><td>Poses</td><td>{caps.poses===null?'unknown':caps.poses?'available':'absent — identity pose'}</td></tr>
      <tr><td>Timestamps</td><td>{caps.timestamps===null?'unknown':caps.timestamps?'available':'absent'}</td></tr>
      <tr><td title="Semantic classes come from dataset labels unless a model checkpoint is configured">Semantic capability</td><td>{caps.semantic}</td></tr>
      <tr><td title="Temporal tracking needs dataset timestamps and world-frame poses">Motion capability</td><td>{caps.motion}</td></tr>
     </tbody></table><button class="wide primary" disabled={busy||!catalog?.root||!sequence} onclick={openDirect}>Open dataset & preview</button>{:else}<p class="hint">Data stays in its original directory. A generic dataset uses a manifest.json file.</p>{/if}</section>
     <section class="card"><h3>Preview settings <span>APPLIED WHEN OPENING</span></h3><div class="preset-grid">{#each ['LowResource','Performance','Balanced','Quality'] as name}<button disabled={busy} class:active={preset===name} onclick={()=>{preset=name;applyPreset();}}>{name==='LowResource'?'Low resource':name}</button>{/each}</div><div class="data-row"><span>Point display budget</span><b>{format(config.visualization?.point_budget,0)}</b></div><div class="data-row"><span>Cell display budget</span><b>{format(config.visualization?.cell_budget,0)}</b></div><div class="data-row"><span>Visualization updates</span><b>{config.visualization?.update_hz} Hz</b></div><div class="data-row"><span>Replay limit</span><b>{config.playback?.full_sequence?'Full sequence':`${config.playback?.frame_limit??30} frames`}</b></div><label><input type="checkbox" disabled={busy} checked={config.playback?.full_sequence??false} onchange={event=>{config={...config,playback:{...config.playback,full_sequence:event.currentTarget.checked}};refreshText();}}/> Full sequence (more processing and memory)</label><p class="hint">New sessions default to 30 frames. Save a preset to retain custom overrides. Display budgets do not reduce mapper input; every accepted frame is processed in full.</p><label for="default-policy">Map policy</label><select disabled={busy} id="default-policy" value={config.map?.policy} onchange={event=>{config={...config,map:{...config.map,policy:event.currentTarget.value}};refreshText();}}>{#each policies as policy}<option value={policy}>{labels[policy]}</option>{/each}</select></section></div>
    <details class="card"><summary>Advanced session configuration</summary><h3>Session configuration <span>JSON</span></h3><textarea aria-label="Session configuration JSON" bind:value={configText} spellcheck="false" rows="17"></textarea><div class="form-actions"><button disabled={busy} onclick={()=>action(async()=>{await window.veyra.validateConfig(JSON.parse(configText));notice='Configuration is valid.';})}>Validate</button><button disabled={busy} onclick={()=>action(async()=>{const saved=await window.veyra.saveConfig(JSON.parse(configText));confirmSaved(saved,'Configuration preset saved.','Preset save cancelled — no file written.');})}>Save preset</button><button class="primary" disabled={busy||!config.dataset_root} onclick={configure}>{busy?'Working…':'Apply configuration & preview'}</button></div></details>
   </div>
  {/if}
 </main>
</div>
